// fir_comp.v - CIC droop-compensation FIR (Block 8), placed after cic3 (Block 7).
//
// y[n] = (sum_{k=0}^{NTAP-1} c[k] * x[n-k] + 2^(F-1)) >>> F
// Linear-phase type-I FIR, NTAP taps, coefficients signed CW bits with F
// fractional bits (sum of taps = 2^F, DC gain exactly 1). Coefficients are
// generated by python/fir_ref.py into rtl/fir_coefs.vh. Bit-exact against
// python/fir_ref.py.
//
// Architecture: one multiplier, one tap per clock (serial MAC). After a
// din_valid pulse the output appears NTAP+1 clocks later with a dout_valid
// pulse. din_valid must be at least NTAP+2 clocks apart; a pulse that arrives
// while the MAC is busy is dropped and counted in 'overrun' (sticky).
// With fs_out = 50 kHz and a 27 MHz clock there are 540 clocks per sample.
//
// Widths: worst-case |acc| = sum|c| * 512000 < 2^37 (ACC = 38) and worst-case
// |y| = 909039 < 2^20 (W_OUT = 21), checked by python/fir_ref.py (check 3).
module fir_comp #(
    parameter W_IN  = 20,
    parameter W_OUT = 21,
    parameter NTAP  = 21,
    parameter CW    = 18,
    parameter F     = 16,
    parameter ACC   = 38
)(
    input  wire                    clk,
    input  wire                    rst,        // synchronous, active high
    input  wire                    din_valid,  // one pulse per CIC output
    input  wire signed [W_IN-1:0]  din,
    output reg                     dout_valid,
    output reg  signed [W_OUT-1:0] dout,
    output reg                     overrun     // sticky: din_valid while busy
);
    localparam KW = $clog2(NTAP);

    function signed [CW-1:0] coef(input [KW-1:0] k);
        begin
            case (k)
`include "fir_coefs.vh"
            default: coef = {CW{1'b0}};
            endcase
        end
    endfunction

    reg signed [W_IN-1:0] xs [0:NTAP-1];    // xs[0] = newest sample x[n]
    reg signed [ACC-1:0]  acc;
    reg        [KW-1:0]   k;
    reg                   busy;
    integer               i;

    wire signed [CW+W_IN-1:0] prod = coef(k) * xs[k];
    wire signed [ACC-1:0]     accn = acc + {{(ACC-CW-W_IN){prod[CW+W_IN-1]}}, prod};
    wire signed [ACC-1:0]     rnd  = accn + ({{(ACC-1){1'b0}}, 1'b1} <<< (F-1));
    wire signed [ACC-1:0]     ysh  = rnd >>> F;

    always @(posedge clk) begin
        dout_valid <= 1'b0;
        if (rst) begin
            for (i = 0; i < NTAP; i = i + 1) xs[i] <= {W_IN{1'b0}};
            acc <= {ACC{1'b0}}; k <= {KW{1'b0}}; busy <= 1'b0;
            dout <= {W_OUT{1'b0}}; overrun <= 1'b0;
        end else begin
            if (din_valid) begin
                if (busy) begin
                    overrun <= 1'b1;
                end else begin
                    xs[0] <= din;
                    for (i = 1; i < NTAP; i = i + 1) xs[i] <= xs[i-1];
                    acc  <= {ACC{1'b0}};
                    k    <= {KW{1'b0}};
                    busy <= 1'b1;
                end
            end
            if (busy) begin
                if (k == NTAP-1) begin
                    dout       <= ysh[W_OUT-1:0];
                    dout_valid <= 1'b1;
                    busy       <= 1'b0;
                end else begin
                    acc <= accn;
                    k   <= k + 1'b1;
                end
            end
        end
    end
endmodule
